// Native bridge for the Floem OpenHarmony example.
//
// Two responsibilities:
//
// 1. Drive the floem `ohos` runtime: the Rust cdylib (`libohos.so`) exports the
//    `ohos_winit_runtime_*` C-ABI symbols generated by
//    `floem_winit_ohos::export_ohos_winit_app!`. Those are plain C functions,
//    so ArkTS cannot call them directly — this bridge registers XComponent
//    callbacks (surface lifecycle / touch / frame) and forwards them.
// 2. Keep the small N-API surface the ArkTS shell uses (`setScaleFactor` /
//    `setFontScale`). `getMessage` / `incrementCounter` are kept as harmless
//    local stubs so the generated page still compiles; they intentionally no
//    longer reference any Rust symbol.
//
// The Rust cdylib `libohos.so` is linked as a *shared* library (see
// CMakeLists.txt) and carries the floem `#[napi]` surface
// (`register_platform_bridge` / `on_file_picked` / `on_shared_files` / …). It is
// deliberately **not** imported from ArkTS as its own N-API module: napi-rs 2.x
// never calls `napi_module_register` on OHOS, so the .so is invisible to OHOS's
// module manager and `import … from 'libohos.so'` resolves to a different module
// (`Name mismatch: default/ohos != default/entry`, then `Module path conflict`),
// leaving every floem export `undefined`. Instead this file — the HAP's one
// registered N-API module, "entry" — forwards to libohos.so's standard entry
// `napi_register_module_v1`, so ArkTS reaches the Rust bridge through
// `import … from 'libentry.so'`.

#include <ace/xcomponent/native_interface_xcomponent.h>
#include <hilog/log.h>
#include <napi/native_api.h>

#include <cmath>
#include <cstdint>

extern "C" {
// --- floem-winit-ohos runtime (exported by libohos.so) ---
void* ohos_winit_runtime_new();
void ohos_winit_runtime_free(void* runtime);
void ohos_winit_runtime_surface_created(const void* runtime, void* xcomponent, void* native_window,
    uint32_t width, uint32_t height, double density_scale, double font_scale);
void ohos_winit_runtime_surface_changed(const void* runtime, void* xcomponent, void* native_window,
    uint32_t width, uint32_t height, double density_scale, double font_scale);
void ohos_winit_runtime_surface_destroyed(const void* runtime);
void ohos_winit_runtime_focus(const void* runtime, bool focused);
void ohos_winit_runtime_visibility(const void* runtime, bool visible);
void ohos_winit_runtime_low_memory(const void* runtime);
void ohos_winit_runtime_frame(const void* runtime);
void ohos_winit_runtime_key(
    const void* runtime, uint32_t action, uint32_t key_code, bool repeat, int64_t device_id);
void ohos_winit_runtime_touch(const void* runtime, uint32_t action, uint32_t source, uint64_t finger_id,
    double x, double y, double force, bool has_force, int64_t device_id, bool primary);
void ohos_winit_runtime_mouse(const void* runtime, uint32_t action, uint32_t button, bool has_button,
    double x, double y, double delta_x, double delta_y, int64_t device_id, bool primary);

// --- floem N-API exports (also exported by libohos.so) ---
// napi-rs' module entry. It fills the exports object it is handed (rather than
// returning a fresh one) and is safe to call more than once, so libentry.so can
// invoke it to merge the Rust bridge into its own exports.
napi_value napi_register_module_v1(napi_env env, napi_value exports);
}

namespace {

constexpr unsigned int DEFAULT_LOG_DOMAIN = 0x3433;
constexpr const char* DEFAULT_LOG_TAG = "floem";

void* g_runtime = nullptr;
OH_NativeXComponent* g_component = nullptr;
// MUST outlive RegisterXComponent: OH_NativeXComponent_RegisterCallback keeps
// the *pointer*, it does not copy the struct. A function-local callback would
// dangle the moment registration returned and ACE would then call through a
// stale stack slot — a wild jump into heap/stack junk on surface creation.
OH_NativeXComponent_Callback g_callback = {};
double g_density_scale = 1.0;
double g_font_scale = 1.0;
uint32_t g_local_counter = 0;

double NormalizePositiveValue(double value)
{
    if (std::isfinite(value) && value > 0.0) {
        return value;
    }
    return 1.0;
}

void Log(const char* message)
{
    OH_LOG_Print(LOG_APP, LOG_INFO, DEFAULT_LOG_DOMAIN, DEFAULT_LOG_TAG, "%{public}s", message);
}

void EnsureRuntime()
{
    if (g_runtime == nullptr) {
        g_runtime = ohos_winit_runtime_new();
    }
}

} // namespace

// ---------------------------------------------------------------------------
// Host log bridge for the Rust runtime
// ---------------------------------------------------------------------------

// `floem_winit_ohos::{deveco_log, deveco_log_with_level}`
// (vendor/floem-winit-ohos/src/log.rs) do not call hilog themselves; they
// forward to this host-provided C symbol:
//
//     int cargo_ohos_app_hilog(uint32_t level, uint32_t domain,
//                              const char* tag, const char* message);
//
// libohos.so carries it as an *undefined* symbol, so it must be present in
// libentry.so's dynamic symbol table or the OHOS loader cannot relocate
// libohos.so at all — and the whole native bridge (XComponent callbacks
// included) never comes up. Keep it non-static and non-hidden.
extern "C" int cargo_ohos_app_hilog(
    uint32_t level, uint32_t domain, const char* tag, const char* message)
{
    OH_LOG_Print(LOG_APP, static_cast<LogLevel>(level), domain == 0 ? DEFAULT_LOG_DOMAIN : domain,
        (tag != nullptr && tag[0] != '\0') ? tag : DEFAULT_LOG_TAG, "%{public}s",
        message != nullptr ? message : "");
    return 0;
}

// ---------------------------------------------------------------------------
// XComponent callbacks → floem runtime
// ---------------------------------------------------------------------------

static void OnSurfaceCreated(OH_NativeXComponent* component, void* window)
{
    EnsureRuntime();
    if (g_runtime == nullptr) {
        Log("floem runtime unavailable");
        return;
    }

    uint64_t width = 0;
    uint64_t height = 0;
    if (OH_NativeXComponent_GetXComponentSize(component, window, &width, &height) !=
        OH_NATIVEXCOMPONENT_RESULT_SUCCESS) {
        Log("failed to read XComponent size");
    }

    ohos_winit_runtime_surface_created(g_runtime, component, window, static_cast<uint32_t>(width),
        static_cast<uint32_t>(height), g_density_scale, g_font_scale);
}

static void OnSurfaceChanged(OH_NativeXComponent* component, void* window)
{
    if (g_runtime == nullptr) {
        return;
    }

    uint64_t width = 0;
    uint64_t height = 0;
    OH_NativeXComponent_GetXComponentSize(component, window, &width, &height);

    ohos_winit_runtime_surface_changed(g_runtime, component, window, static_cast<uint32_t>(width),
        static_cast<uint32_t>(height), g_density_scale, g_font_scale);
}

static void OnSurfaceDestroyed(OH_NativeXComponent* component, void* window)
{
    if (g_runtime == nullptr) {
        return;
    }
    ohos_winit_runtime_surface_destroyed(g_runtime);
    ohos_winit_runtime_free(g_runtime);
    g_runtime = nullptr;
}

static void DispatchTouchEvent(OH_NativeXComponent* component, void* window)
{
    if (g_runtime == nullptr) {
        return;
    }

    OH_NativeXComponent_TouchEvent touchEvent {};
    if (OH_NativeXComponent_GetTouchEvent(component, window, &touchEvent) !=
        OH_NATIVEXCOMPONENT_RESULT_SUCCESS) {
        return;
    }

    // Forward the primary point. `screenX/screenY` are window-relative, which is
    // what winit expects; fall back to the XComponent-local x/y when unset.
    double px = touchEvent.touchPoints[0].screenX;
    double py = touchEvent.touchPoints[0].screenY;
    if (px == 0.0 && py == 0.0) {
        px = touchEvent.touchPoints[0].x;
        py = touchEvent.touchPoints[0].y;
    }

    ohos_winit_runtime_touch(g_runtime, static_cast<uint32_t>(touchEvent.type), 0,
        static_cast<uint64_t>(touchEvent.touchPoints[0].id), px, py,
        touchEvent.touchPoints[0].force, false, 0, true);
}

static void OnFrame(OH_NativeXComponent* component, uint64_t timestamp, uint64_t targetTimestamp)
{
    if (g_runtime == nullptr) {
        return;
    }
    ohos_winit_runtime_frame(g_runtime);
}

static void RegisterXComponent(napi_env env, napi_value exports)
{
    napi_value exportInstance = nullptr;
    if (napi_get_named_property(env, exports, OH_NATIVE_XCOMPONENT_OBJ, &exportInstance) != napi_ok ||
        exportInstance == nullptr) {
        return;
    }

    OH_NativeXComponent* component = nullptr;
    if (napi_unwrap(env, exportInstance, reinterpret_cast<void**>(&component)) != napi_ok ||
        component == nullptr) {
        return;
    }
    g_component = component;

    g_callback.OnSurfaceCreated = OnSurfaceCreated;
    g_callback.OnSurfaceChanged = OnSurfaceChanged;
    g_callback.OnSurfaceDestroyed = OnSurfaceDestroyed;
    g_callback.DispatchTouchEvent = DispatchTouchEvent;
    OH_NativeXComponent_RegisterCallback(component, &g_callback);
    OH_NativeXComponent_RegisterOnFrameCallback(component, OnFrame);
}

// ---------------------------------------------------------------------------
// N-API surface used by the ArkTS shell
// ---------------------------------------------------------------------------

static napi_value GetMessage(napi_env env, napi_callback_info info)
{
    napi_value result = nullptr;
    napi_create_string_utf8(env, "floem on OpenHarmony", NAPI_AUTO_LENGTH, &result);
    return result;
}

static napi_value IncrementCounter(napi_env env, napi_callback_info info)
{
    napi_value result = nullptr;
    napi_create_uint32(env, ++g_local_counter, &result);
    return result;
}

static napi_value SetScaleFactor(napi_env env, napi_callback_info info)
{
    size_t argc = 1;
    napi_value args[1] = { nullptr };
    if (napi_get_cb_info(env, info, &argc, args, nullptr, nullptr) != napi_ok || argc != 1) {
        return nullptr;
    }

    double scaleFactor = 1.0;
    if (napi_get_value_double(env, args[0], &scaleFactor) != napi_ok) {
        return nullptr;
    }

    g_density_scale = NormalizePositiveValue(scaleFactor);

    napi_value result = nullptr;
    napi_get_undefined(env, &result);
    return result;
}

static napi_value SetFontScale(napi_env env, napi_callback_info info)
{
    size_t argc = 1;
    napi_value args[1] = { nullptr };
    if (napi_get_cb_info(env, info, &argc, args, nullptr, nullptr) != napi_ok || argc != 1) {
        return nullptr;
    }

    double fontScale = 1.0;
    if (napi_get_value_double(env, args[0], &fontScale) != napi_ok) {
        return nullptr;
    }

    g_font_scale = NormalizePositiveValue(fontScale);

    napi_value result = nullptr;
    napi_get_undefined(env, &result);
    return result;
}

static napi_value Init(napi_env env, napi_value exports)
{
    napi_property_descriptor descriptors[] = {
        { "getMessage", nullptr, GetMessage, nullptr, nullptr, nullptr, napi_default, nullptr },
        { "incrementCounter", nullptr, IncrementCounter, nullptr, nullptr, nullptr, napi_default, nullptr },
        { "setScaleFactor", nullptr, SetScaleFactor, nullptr, nullptr, nullptr, napi_default, nullptr },
        { "setFontScale", nullptr, SetFontScale, nullptr, nullptr, nullptr, napi_default, nullptr }
    };
    napi_define_properties(env, exports, sizeof(descriptors) / sizeof(descriptors[0]), descriptors);

    RegisterXComponent(env, exports);

    // Merge the Rust N-API bridge (libohos.so) into this module's exports so
    // ArkTS reaches `registerPlatformBridge` / `on*` via 'libentry.so'. napi-rs
    // registers its exports through a `#[ctor]` in libohos.so's `.init_array`
    // and exposes the standard `napi_register_module_v1(env, exports)` entry to
    // fill them in. Called last: the XComponent callbacks above must survive
    // even if the Rust side fails to register.
    napi_register_module_v1(env, exports);
    return exports;
}

static napi_module cargoOhosAppModule = {
    .nm_version = 1,
    .nm_flags = 0,
    .nm_filename = nullptr,
    .nm_register_func = Init,
    .nm_modname = "entry",
    .nm_priv = nullptr,
    .reserved = { 0 }
};

extern "C" __attribute__((constructor)) void RegisterCargoOhosAppModule(void)
{
    napi_module_register(&cargoOhosAppModule);
}
